import{_ as n,o as r,c as i,a2 as t}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Regeln der Ebenendurchquerung","description":"","frontmatter":{},"headers":[],"relativePath":"de/81-位面穿梭规则.md","filePath":"de/81-位面穿梭规则.md","lastUpdated":null}'),u={name:"de/81-位面穿梭规则.md"};function s(d,e,h,a,g,l){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="regeln-der-ebenendurchquerung" tabindex="-1">Regeln der Ebenendurchquerung <a class="header-anchor" href="#regeln-der-ebenendurchquerung" aria-label="Permalink to &quot;Regeln der Ebenendurchquerung&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Punkt</th><th>Inhalt</th></tr></thead><tbody><tr><td>Dokumentennummer</td><td>81</td></tr><tr><td>Modul</td><td>Interdimensionale Interaktion und Zeitregeln</td></tr><tr><td>Kernschlüsselwörter</td><td>Ebenendurchquerung, Durchquerungsgenehmigung, Energieschwelle, Anker-Kalibrierung, Verschmutzungsprävention</td></tr></tbody></table><h2 id="_1-rechtliche-einordnung-des-durchquerungsaktes" tabindex="-1">1. Rechtliche Einordnung des Durchquerungsaktes <a class="header-anchor" href="#_1-rechtliche-einordnung-des-durchquerungsaktes" aria-label="Permalink to &quot;1. Rechtliche Einordnung des Durchquerungsaktes&quot;">​</a></h2><p>Ebenendurchquerung bezieht sich auf den Akt, bei dem ein Individuum oder eine Gruppe von Lebewesen durch technische Mittel oder Kultivierungsfähigkeiten die Gesetzesbarriere überquert, um von einer Ebene in eine andere einzutreten. Im rechtlichen Rahmen der Anker-Symbiose-Zivilisation wird die Ebenendurchquerung als &quot;sonderakt mit hohem Risiko&quot; eingestuft und muss einer strengen Genehmigungsverwaltung und Prozessaufsicht unterliegen. Artikel 47 der &quot;Symbiose-Verfassung&quot; legt ausdrücklich fest: &quot;Keine Organisation und kein Einzelner darf ohne Genehmigung eigenmächtig eine interdimensionale Durchquerung durchführen, noch die Ebenendurchquerung nutzen, um Raub, Einmischung oder Verschmutzung gegen Zivilisationen anderer Ebenen zu betreiben.&quot;</p><p>Der grundlegende Grund, warum die Ebenendurchquerung einer strengen Kontrolle bedarf, liegt darin, dass der Durchquerungsakt selbst multiple Auswirkungen auf die Zielebene haben kann: Gesetzesstörung, Energieinjektion, Bewusstseinsverschmutzung, mikrobielle Invasion und kulturelle Einmischung, unter anderem. Diese Auswirkungen verursachen in leichtem Grad lokale Anomalien in der Zielebene; in schwerem Grad können sie die Evolutionsbahn ihrer Zivilisation verändern und sogar zum Zusammenbruch der Gesetze führen. Daher ist das zentrale Ziel der Durchquerungsregeln &quot;die externen Auswirkungen des Durchquerungsaktes innerhalb akzeptabler Schwellen zu kontrollieren&quot;.</p><h2 id="_2-klassifizierungssystem-der-durchquerungsgenehmigungen" tabindex="-1">2. Klassifizierungssystem der Durchquerungsgenehmigungen <a class="header-anchor" href="#_2-klassifizierungssystem-der-durchquerungsgenehmigungen" aria-label="Permalink to &quot;2. Klassifizierungssystem der Durchquerungsgenehmigungen&quot;">​</a></h2><p>Hengyuanzhou implementiert ein Klassifizierungssystem für Ebenendurchquerungsgenehmigungen, das Genehmigungen nach dem Zweck der Durchquerung, dem Typ der Zielebene und der Qualifikation des Durchquerers in vier Ebenen unterteilt:</p><table tabindex="0"><thead><tr><th>Genehmigungsebene</th><th>Anwendbares Szenario</th><th>Genehmigungsbehörde</th><th>Gültigkeitsdauer</th><th>Zusätzliche Bedingungen</th></tr></thead><tbody><tr><td>Ebene A (Archäologische Beobachtung)</td><td>Rein beobachtende Archäologie, ohne jeglichen physischen Kontakt</td><td>Ebenenverwaltungsbehörde</td><td>Einzelne Mission</td><td>Muss das Kopierspiegel- + Isolationsraum-Schema verwenden</td></tr><tr><td>Ebene B (Akademischer Austausch)</td><td>Begrenzter Wissensaustausch mit der Zivilisation der Zielebene</td><td>Ebenenverwaltungsbehörde + Kulturministerium</td><td>Maximal ein Jahr</td><td>Muss Vereinbarung über gegenseitige Nicht-Einmischung unterzeichnen</td></tr><tr><td>Ebene C (Ressourcenkooperation)</td><td>Zusammenarbeit bei Ressourcen und Technologie unter der Prämisse von Gleichheit und gegenseitigem Nutzen</td><td>Sonder genehmigung des Anker-Rats</td><td>Maximal drei Jahre</td><td>Muss Zustimmung der Zivilisation der Zielebene einholen</td></tr><tr><td>Ebene D (Notfallintervention)</td><td>Humanitäre Intervention, wenn die Zielebene einer Krise auf Aussterbeebene gegenübersteht</td><td>Dringende Resolution des Anker-Rats</td><td>Während der Krise</td><td>Muss anschließend vollständigen Interventionsbericht vorlegen</td></tr></tbody></table><p>Jede Ebene der Durchquerungsgenehmigung verbietet folgende Handlungen: die Ursprungsenergie der Zielebene zu rauben, die Ideologie der eigenen Ebene gewaltsam zu verbreiten, genetische oder bewusstseinsmäßige Veränderungen ohne Zustimmung durchzuführen, dauerhafte Militärstützpunkte in der Zielebene zu errichten, und jede Form von Kolonialherrschaft.</p><h2 id="_3-technische-anforderungen-und-energieschwelle-der-durchquerung" tabindex="-1">3. Technische Anforderungen und Energieschwelle der Durchquerung <a class="header-anchor" href="#_3-technische-anforderungen-und-energieschwelle-der-durchquerung" aria-label="Permalink to &quot;3. Technische Anforderungen und Energieschwelle der Durchquerung&quot;">​</a></h2><p>Die Ebenendurchquerung erfordert die Erfüllung strenger technischer Bedingungen. Erstens muss der Durchquerer über eine Kultivierung der dritten Stufe (Zustand der Raumtransformation) oder höher des &quot;Raum-Recht-Regulierungssystems&quot; verfügen oder ein standardkonformes Ebenendurchquerungsfahrzeug mitführen. Zweitens müssen sowohl Start- als auch Endpunkt der Durchquerung Anker zur Koordinatenkalibrierung haben; blinde Durchquerung ohne Anker-Positionierung ist strengstens verboten.</p><p>Der Energieverbrauch während des Durchquerungsprozesses ist direkt proportional zur Intensität der Gesetzesbarriere der Zielebene. Hengyuanzhou hat eine standardisierte &quot;Tabelle der Durchquerungs-Energieschwellen&quot; eingerichtet, und die für die Durchquerung verschiedener Ebenentypen erforderliche Mindestenergie ist wie folgt:</p><ul><li>Materielle Grundebene: 1000 Standard-Energieeinheiten</li><li>Energie-Manifestationsebene: 5000 Standard-Energieeinheiten</li><li>Bewusstseins-dominierte Ebene: 20000 Standard-Energieeinheiten</li><li>Ebene mit gebrochenen Gesetzen: 50000 Standard-Energieeinheiten (und Erfolgsrate unter 30%)</li><li>Ebene nahe dem Ursprung: theoretischer Wert über 100000, derzeit keine Erfolgsaufzeichnungen</li></ul><p>Die Durchquerungsenergie muss vom Durchquerer oder dem Fahrzeug selbst mitgeführt werden; es ist verboten, Energie aus der Zielebene für den Durchquerungsprozess zu extrahieren. Diese Bestimmung zielt darauf ab, zu verhindern, dass der Durchquerungsakt Energie-Raub in der Zielebene verursacht.</p><h2 id="_4-verschmutzungspravention-im-durchquerungsprozess" tabindex="-1">4. Verschmutzungsprävention im Durchquerungsprozess <a class="header-anchor" href="#_4-verschmutzungspravention-im-durchquerungsprozess" aria-label="Permalink to &quot;4. Verschmutzungsprävention im Durchquerungsprozess&quot;">​</a></h2><p>Eines der größten Risiken der Ebenendurchquerung ist die &quot;interdimensionale Verschmutzung&quot;, einschließlich biologischer Verschmutzung (Mitführen von Mikroorganismen der eigenen Ebene in die Zielebene), Energieverschmutzung (Störung von Energie Resten der eigenen Ebene auf die Gesetze der Zielebene) und Bewusstseinsverschmutzung (Bewusstseinsschwankungen des Durchquerers beeinflussen das Bewusstseinsgebiet der Zielebene).</p><p>Zur Verschmutzungsprävention müssen alle Durchquerer vor der Abreise das &quot;Drei-Stufen-Reinigungsprogramm&quot; abschließen:</p><ol><li><strong>Biologische Reinigung</strong>: Durchführung einer 72-stündigen mikrobiellen Screening und Beseitigung im Isolationsraum, um sicherzustellen, dass keine Krankheitserreger der eigenen Ebene mitgeführt werden</li><li><strong>Energetische Reinigung</strong>: Anpassung der Energiefrequenz des Durchquerers auf einen mit der Zielebene kompatiblen Bereich durch das Anker-Kalibrierungsgerät, um Energie-Abstoßungsreaktionen zu reduzieren</li><li><strong>Bewusstseinsreinigung</strong>: Durchführung von Bewusstseins-Abschirmungstraining, um sicherzustellen, dass während des Durchquerungsprozesses keine Willensschwankungen aktiv freigesetzt werden, die das Bewusstseinsgebiet der Zielebene stören könnten</li></ol><p>Darüber hinaus ist der Tätigkeitsbereich des Durchquerers in der Zielebene streng auf den &quot;durch die Durchquerungsgenehmigung festgelegten Bereich&quot; beschränkt; unbefugte Ausbreitung ist verboten. Nach der Rückkehr in die eigene Ebene muss der Durchquerer erneut eine Isolationsbeobachtung durchlaufen, die nicht weniger als 30 Tage beträgt, umgerechnet nach der Zeitflussgeschwindigkeit der Zielebene.</p><h2 id="schlussfolgerung" tabindex="-1">Schlussfolgerung <a class="header-anchor" href="#schlussfolgerung" aria-label="Permalink to &quot;Schlussfolgerung&quot;">​</a></h2><p>Die Regeln der Ebenendurchquerung sind die erste Sicherheitsverteidigungslinie der interdimensionalen Interaktion. Durch drei Mechanismen — Genehmigungsklassifizierung, technische Schwellen und Verschmutzungsprävention — wird sichergestellt, dass der Durchquerungsakt stets auf der Bahn von &quot;geringer Auswirkung, nachverfolgbar, rechenschaftspflichtig&quot; operiert. Das ultimative Ziel der Regeln ist nicht, den Austausch zwischen Zivilisationen einzuschränken, sondern den Austausch auf symbiotische Weise statt auf räuberische Weise stattfinden zu lassen.</p><h2 id="verwandte-dokumente" tabindex="-1">Verwandte Dokumente <a class="header-anchor" href="#verwandte-dokumente" aria-label="Permalink to &quot;Verwandte Dokumente&quot;">​</a></h2><ul><li>80-Theorie und Klassifikation der Ebenen</li><li>88-Ethische Richtlinien für die Interdimensionale Interaktion</li><li>62-Technische Umsetzung des Raum-Rechts</li></ul>',23)])])}const b=n(u,[["render",s]]);export{c as __pageData,b as default};
